import cache


def _normalize(raw):
    result = []
    prev_underscore = False
    for ch in raw.lower():
        if ch.isalnum():
            result.append(ch)
            prev_underscore = False
        else:
            if not prev_underscore:
                result.append('_')
                prev_underscore = True
    key = ''.join(result).strip('_')
    return 'kx7-' + key


def store(k, v, secs):
    normalized = _normalize(k)
    existed = cache.get(normalized) is not None
    cache.put(normalized, v, secs)
    return not existed

from . import cache

def store(k, v, secs):
    raw = str(k)
    lower = raw.lower()
    normalized = []
    for ch in lower:
        if ch.isalnum():
            normalized.append(ch)
        else:
            if not normalized or normalized[-1] != '_':
                normalized.append('_')
    key_body = ''.join(normalized).strip('_')
    cache_key = f'kx7-{key_body}'
    return cache.put(cache_key, v, ttl=secs)

