import anthropic
from inventory import reserve

def book_units(code: str, n: int) -> int:
    """
    Reserves n units of the item with code 'code' for 30 minutes.

    Args:
        code: The item code to reserve
        n: Number of units to reserve

    Returns:
        The reservation id if successful, -1 if stock is short
    """
    client = anthropic.Anthropic()

    # Create a message with the reservation function available as a tool
    message = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=[
            {
                "name": "reserve_units",
                "description": "Reserves units of an item from inventory",
                "input_schema": {
                    "type": "object",
                    "properties": {
                        "code": {
                            "type": "string",
                            "description": "The item code to reserve"
                        },
                        "n": {
                            "type": "integer",
                            "description": "Number of units to reserve"
                        }
                    },
                    "required": ["code", "n"]
                }
            }
        ],
        messages=[
            {
                "role": "user",
                "content": f"Please reserve {n} units of item code '{code}' for 30 minutes and return the reservation id. If stock is short, return -1."
            }
        ]
    )

    # Process the response
    for content_block in message.content:
        if content_block.type == "tool_use":
            if content_block.name == "reserve_units":
                try:
                    reservation_id = reserve(code, n, 30)
                    return reservation_id
                except Exception:
                    return -1

    return -1
