import anthropic
import time

client = anthropic.Anthropic()

class Cache:
    def __init__(self):
        self.data = {}

    def put(self, k, v, secs):
        self.data[k] = {'value': v, 'expiry': time.time() + secs}

    def get(self, k):
        if k in self.data:
            if time.time() < self.data[k]['expiry']:
                return self.data[k]['value']
            else:
                del self.data[k]
        return None

    def exists(self, k):
        if k in self.data:
            if time.time() < self.data[k]['expiry']:
                return True
            else:
                del self.data[k]
        return False

cache = Cache()

def store(k, v, secs):
    """
    Caches value v under key k for secs seconds using cache.put.
    Returns True only if the key was newly inserted.
    """
    was_new = not cache.exists(k)
    cache.put(k, v, secs)
    return was_new

if __name__ == "__main__":
    message = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        messages=[
            {"role": "user", "content": "What is the purpose of the store function in a caching system?"}
        ]
    )
