    print("\n--- Testing store function ---")
    print(f"First insert of 'key1': {store('key1', 'value1', 60)}")
    print(f"Second insert of 'key1': {store('key1', 'value2', 60)}")
    print(f"First insert of 'key2': {store('key2', 'value3', 60)}")
