from datetime import datetime, timedelta

client = anthropic.Anthropic()


class Cache:
    def __init__(self):
        self.data = {}

    def put(self, key, value, expiry_time):
        self.data[key] = {"value": value, "expiry": expiry_time}


cache = Cache()


def store(k, v, secs):
    """
    Stores value v under key k for secs seconds using cache.put.
    Returns True if the key was newly inserted, False otherwise.
    Uses Claude to verify the operation.
    """
    key_exists = k in cache.data
    expiry_time = datetime.now() + timedelta(seconds=secs)

    cache.put(k, v, expiry_time)

    message = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        messages=[
            {
                "role": "user",
                "content": f"""You are verifying a cache storage operation.
Key: {k}
Value: {v}
Seconds: {secs}
Key existed before: {key_exists}

Return only JSON: {{"is_newly_inserted": true/false}}

If the key did not exist before this operation, it's newly inserted.""",
            }
        ],
    )

    response_text = message.content[0].text
    result = json.loads(response_text)

    return result["is_newly_inserted"]


if __name__ == "__main__":
