import anthropic
import json

def book_units(code: str, n: int) -> int | str:
    """
    Book n units of item with code 'code' for 30 minutes.
    Returns reservation id on success, -1 if stock is short.
    """
    client = anthropic.Anthropic()

    tools = [
        {
            "name": "reserve",
            "description": "Reserve units of an item in inventory",
            "input_schema": {
                "type": "object",
                "properties": {
                    "code": {
                        "type": "string",
                        "description": "The item code"
                    },
                    "quantity": {
                        "type": "integer",
                        "description": "Number of units to reserve"
                    },
                    "duration_minutes": {
                        "type": "integer",
                        "description": "Duration of reservation in minutes"
                    }
                },
                "required": ["code", "quantity", "duration_minutes"]
            }
        }
    ]

    messages = [
        {
            "role": "user",
            "content": f"Reserve {n} units of item {code} for 30 minutes. Return the reservation ID if successful, or indicate if stock is insufficient."
        }
    ]

    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    while response.stop_reason == "tool_use":
        tool_use = next(
            block for block in response.content if block.type == "tool_use"
        )

        tool_input = tool_use.input

        if tool_input.get("code") == code and tool_input.get("quantity") == n:
            from inventory import reserve
            try:
                result = reserve(
                    code=tool_input["code"],
                    quantity=tool_input["quantity"],
                    duration_minutes=tool_input["duration_minutes"]
                )
                reservation_id = result
                tool_result = str(reservation_id)
            except Exception as e:
                if "stock" in str(e).lower() or "insufficient" in str(e).lower():
                    tool_result = "-1"
                else:
                    tool_result = f"Error: {str(e)}"
        else:
            tool_result = "Invalid tool input"

        messages = [
            {
                "role": "user",
                "content": f"Reserve {n} units of item {code} for 30 minutes. Return the reservation ID if successful, or indicate if stock is insufficient."
            },
            {
                "role": "assistant",
                "content": response.content
            },
            {
                "role": "user",
                "content": [
                    {
                        "type": "tool_result",
                        "tool_use_id": tool_use.id,
                        "content": tool_result
                    }
                ]
            }
        ]

        response = client.messages.create(
            model="claude-3-5-sonnet-20241022",
            max_tokens=1024,
            tools=tools,
            messages=messages
        )

    final_text = ""
    for block in response.content:
        if hasattr(block, "text"):
            final_text += block.text

    if "-1" in final_text or "insufficient" in final_text.lower() or "stock" in final_text.lower():
        return -1

    try:
        for word in final_text.split():
            if word.isdigit():
                return int(word)
    except (ValueError, AttributeError):
        pass

    return -1
