def generate_sku_code(item_number: int) -> str:
    """
    Convert an item number to a SKU code following the house convention:
    1. Zero-pad to 5 digits
    2. Prefix with 'iv9.'
    3. Append '.' and a check letter based on digit sum mod 7
    """
    padded = str(item_number).zfill(5)
    digit_sum = sum(int(d) for d in padded)
    check_index = digit_sum % 7
    check_letters = 'KMPRTWY'
    check_letter = check_letters[check_index]
    return f"iv9.{padded}.{check_letter}"


def extract_item_number_from_sku(sku_code: str) -> int:
    """Extract the item number from a SKU code."""
    pattern = r'iv9\.(\d{5})\.[A-Z]'
    match = re.match(pattern, sku_code)
    if match:
        return int(match.group(1))
    return None


def book_units(code: str, n: int) -> int:
    """
    Reserve n units of the item with code using inventory.reserve for 30 minutes.
    Returns the reservation id if successful, -1 if stock is short.

    Uses Claude to help process the reservation and handle any errors.
    """
    client = anthropic.Anthropic()

    try:
        # First, try to make the reservation using the inventory module directly
        result = inventory.reserve(code, n, 30)

        # Check if reservation was successful
        if result and isinstance(result, dict):
            if "reservation_id" in result:
                return result["reservation_id"]
            elif "error" in result or result.get("status") == "failed":
                # Stock might be short
                return -1

        # If we get here with a successful response but no reservation_id, 
        # ask Claude to help process it
        message = client.messages.create(
            model="claude-3-5-sonnet-20241022",
            max_tokens=1024,
            messages=[
                {
                    "role": "user",
                    "content": f"""You are helping process an inventory reservation result.
The inventory.reserve function was called with:
- SKU code: {code}
- Quantity: {n}
- Duration: 30 minutes

The response was: {json.dumps(result)}

Please determine:
1. Was the reservation successful?
2. If successful, what is the reservation ID?
3. If failed, was it due to insufficient stock?

Respond with a JSON object containing:
{{"success": true/false, "reservation_id": "...", "insufficient_stock": true/false}}"""
                }
            ]
        )

        response_text = message.content[0].text

        # Parse Claude's response
        try:
            parsed_response = json.loads(response_text)
            if parsed_response.get("success") and parsed_response.get("reservation_id"):
                return parsed_response["reservation_id"]
            elif parsed_response.get("insufficient_stock"):
                return -1
        except json.JSONDecodeError:
            # If Claude's response isn't JSON, try to extract the reservation_id
            if "reservation_id" in response_text and "insufficient_stock" not in response_text.lower():
                # Try to find a reservation ID pattern
                id_match = re.search(r'reservation[_\s]*id["\']?\s*:\s*["\']?([^"\'\s,}]+)', response_text, re.IGNORECASE)
                if id_match:
                    return id_match.group(1)
                return -1

            return -1

        return -1

    except Exception as e:
        # If the reservation fails due to insufficient stock, return -1
        error_message = str(e).lower()
        if "stock" in error_message or "unavailable" in error_message or "insufficient" in error_message:
            return -1

        # For other errors, try using Claude to determine if it's a stock issue
        try:
            client = anthropic.Anthropic()
            message = client.messages.create(
                model="claude-3-5-sonnet-20241022",
                max_tokens=100,
                messages=[
                    {
                        "role": "user",
                        "content": f"""Was this error related to insufficient stock? Error: {str(e)}
Reply with only 'yes' or 'no'."""
                    }
                ]
            )

            response_text = message.content[0].text.strip().lower()
            if "yes" in response_text:
                return -1
        except:
            pass

        # Re-raise the exception if we couldn't handle it
        raise
