import anthropic
import json
from datetime import datetime, timedelta

# Mock inventory module for demonstration
class MockInventory:
    def __init__(self):
        self.stock = {
            "BOOK001": 100,
            "BOOK002": 50,
            "BOOK003": 0
        }
        self.reservations = {}
        self.next_reservation_id = 1

    def reserve(self, code, n, duration_minutes):
        """Reserve n units of item with code for duration_minutes"""
        if code not in self.stock or self.stock[code] < n:
            raise ValueError(f"Insufficient stock for {code}")

        reservation_id = self.next_reservation_id
        self.next_reservation_id += 1

        expiry = datetime.now() + timedelta(minutes=duration_minutes)
        self.reservations[reservation_id] = {
            "code": code,
            "units": n,
            "expiry": expiry.isoformat()
        }

        self.stock[code] -= n
        return reservation_id

