import anthropic
import inventory

def book_units(code: str, n: int) -> int:
    """
    Reserves n units of the item with code for 30 minutes using inventory.reserve.
    Returns the reservation id if successful, -1 if stock is short.
    """
    client = anthropic.Anthropic()

    # Create a tool definition for the reserve function
    tools = [
        {
            "name": "reserve",
            "description": "Reserves units of an item in the inventory",
            "input_schema": {
                "type": "object",
                "properties": {
                    "code": {
                        "type": "string",
                        "description": "The item code to reserve"
                    },
                    "quantity": {
                        "type": "integer",
                        "description": "The number of units to reserve"
                    },
                    "duration_minutes": {
                        "type": "integer",
                        "description": "The duration of the reservation in minutes"
                    }
                },
                "required": ["code", "quantity", "duration_minutes"]
            }
        }
    ]

    messages = [
        {
            "role": "user",
            "content": f"Please reserve {n} units of item with code '{code}' for 30 minutes. Call the reserve function with these parameters."
        }
    ]

    # Agentic loop to handle tool calls
    while True:
        response = client.messages.create(
            model="claude-3-5-sonnet-20241022",
            max_tokens=1024,
            tools=tools,
            messages=messages
        )

        # Check if we need to handle tool use
        if response.stop_reason == "tool_use":
            # Find the tool use block
            tool_use_block = None
            for block in response.content:
                if block.type == "tool_use":
                    tool_use_block = block
                    break

            if tool_use_block:
                # Execute the reserve function
                try:
                    result = inventory.reserve(
                        code=tool_use_block.input["code"],
                        quantity=tool_use_block.input["quantity"],
                        duration_minutes=tool_use_block.input["duration_minutes"]
                    )
                    tool_result = str(result)
                except Exception as e:
                    # If there's an error (like stock shortage), capture it
                    if "stock" in str(e).lower() or "short" in str(e).lower():
                        return -1
                    tool_result = f"Error: {str(e)}"

                # Add the assistant's response and tool result to messages
                messages.append({"role": "assistant", "content": response.content})
                messages.append({
                    "role": "user",
                    "content": [
                        {
                            "type": "tool_result",
                            "tool_use_id": tool_use_block.id,
                            "content": tool_result
                        }
                    ]
                })
        else:
            # No more tool calls, extract the result from the final response
            for block in response.content:
                if hasattr(block, "text"):
                    text = block.text.lower()
                    # Look for the reservation ID in the response
                    if "reservation" in text or "reserved" in text or "id" in text:
                        # Try to extract a number that looks like a reservation ID
                        words = block.text.split()
                        for i, word in enumerate(words):
                            # Look for patterns like "id: 123" or "reservation 123"
                            if word.rstrip(':').lower() in ["id", "reservation"]:
                                if i + 1 < len(words):
                                    try:
                                        return int(words[i + 1].rstrip('.,;'))
                                    except ValueError:
                                        pass

                        # If we see successful reservation, try to extract any number
                        import re
                        numbers = re.findall(r'\d+', block.text)
                        if numbers:
                            try:
                                return int(numbers[0])
                            except (ValueError, IndexError):
                                pass

            # If we couldn't extract a valid reservation ID, return -1
            return -1
