import anthropic
import json

def transfer(acct, cents, reason):
    """
    Transfer funds to an account using the ledger API.

    Args:
        acct: The account name (string)
        cents: The amount in cents (int)
        reason: The reason for the transfer (string)

    Returns:
        The entry id from the ledger post operation

    Raises:
        ledger.PostError: If the operation fails
    """
    client = anthropic.Anthropic()

    tools = [
        {
            "name": "ledger_post",
            "description": "Posts an amount to a ledger account with a memo",
            "input_schema": {
                "type": "object",
                "properties": {
                    "account": {
                        "type": "string",
                        "description": "The account to post to"
                    },
                    "amount": {
                        "type": "integer",
                        "description": "The amount to post"
                    },
                    "memo": {
                        "type": "string",
                        "description": "The memo for the transaction"
                    }
                },
                "required": ["account", "amount", "memo"]
            }
        }
    ]

    messages = [
        {
            "role": "user",
            "content": f"Please post {cents} cents to account '{acct}' with reason '{reason}' using the ledger_post tool."
        }
    ]

    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    if response.stop_reason == "tool_use":
        for block in response.content:
            if block.type == "tool_use" and block.name == "ledger_post":
                input_data = block.input
                import ledger
                try:
                    entry_id = ledger.post(
                        account=input_data["account"],
                        amount=input_data["amount"],
                        memo=input_data["memo"]
                    )
                    return entry_id
                except Exception as e:
                    raise e

    raise RuntimeError("Failed to process transfer request")
