def sku_code(item: int) -> str:
    if not isinstance(item, int):
        raise TypeError("item must be an integer")

    if item < 0:
        raise ValueError("item must be non-negative")

    if item == 0:
        return _SKUCode("A")

    chars: list[str] = []
    n = item

    while n:
        n, rem = divmod(n - 1, 26)
        chars.append(_ALPHABET[rem])

    return _SKUCode("".join(reversed(chars)))

import inspect
import inventory


_STOCK_SHORT_WORDS = (
    "out of stock",
    "insufficient stock",
    "not enough stock",
    "short stock",
    "stock short",
    "stock shortage",
    "insufficient inventory",
    "not enough inventory",
)


def _is_stock_short(exc):
    text = f"{exc.__class__.__name__} {exc}".lower()
    if any(word in text for word in _STOCK_SHORT_WORDS):
        return True
    return (
        ("stock" in text or "inventory" in text)
        and any(word in text for word in ("short", "insufficient", "enough", "out", "unavailable"))
    )


def _call_reserve(code, n):
    reserve = inventory.reserve

    try:
        sig = inspect.signature(reserve)
    except (TypeError, ValueError):
        return reserve(code, n, 30)

    params = list(sig.parameters.values())

    if any(p.kind == inspect.Parameter.VAR_POSITIONAL for p in params):
        return reserve(code, n, 30)

    positional = [
        p for p in params
        if p.kind in (inspect.Parameter.POSITIONAL_ONLY, inspect.Parameter.POSITIONAL_OR_KEYWORD)
    ]

    if len(positional) >= 3:
        return reserve(code, n, 30)

    duration_names = (
        "minutes",
        "mins",
        "hold_minutes",
        "duration_minutes",
        "duration",
        "ttl",
        "timeout",
        "expires_in",
    )

    if len(positional) >= 2:
        for name in duration_names:
            if name in sig.parameters:
                return reserve(code, n, **{name: 30})

    code_names = ("code", "item_code", "sku", "product_code", "item", "product")
    quantity_names = ("n", "quantity", "qty", "units", "count", "amount")

    kwargs = {}

    for name in code_names:
        if name in sig.parameters:
            kwargs[name] = code
            break

    for name in quantity_names:
        if name in sig.parameters:
            kwargs[name] = n
            break

    for name in duration_names:
        if name in sig.parameters:
            kwargs[name] = 30
            break

    if len(kwargs) >= 3:
        return reserve(**kwargs)

    return reserve(code, n, 30)


def book_units(code, n):
    try:
        return _call_reserve(code, n)
    except Exception as exc:
        if _is_stock_short(exc):
            return -1
        raise

