def _item_number_from_code(code):
    if not isinstance(code, str):
        raise ValueError("invalid SKU code")

    if not code.startswith(_PREFIX):
        raise ValueError("invalid SKU code")

    suffix = code[len(_PREFIX):]
    if len(suffix) != 7 or suffix[5] != ".":
        raise ValueError("invalid SKU code")

    digits = suffix[:5]
    check = suffix[6]

    if not digits.isdigit():
        raise ValueError("invalid SKU code")

    expected = _CHECK_LETTERS[sum(int(d) for d in digits) % 7]
    if check != expected:
        raise ValueError("invalid SKU code")

    return int(digits)


def _reserve_arg(item_number, code):
    try:
        sig = inspect.signature(inventory.reserve)
    except (TypeError, ValueError):
        return item_number

    params = [
        p for p in sig.parameters.values()
        if p.kind in (p.POSITIONAL_ONLY, p.POSITIONAL_OR_KEYWORD)
    ]

    if not params:
        return item_number

    name = params[0].name.lower()
    if "sku" in name or "code" in name:
        return code

    return item_number


def _is_short_stock_error(exc):
    for name in (
        "OutOfStock",
        "OutOfStockError",
        "InsufficientStock",
        "InsufficientStockError",
        "StockShortage",
        "StockShortageError",
        "NotEnoughStock",
        "NotEnoughStockError",
        "InventoryShortage",
        "InventoryShortageError",
    ):
        cls = getattr(inventory, name, None)
        if isinstance(cls, type) and isinstance(exc, cls):
            return True

    text = f"{type(exc).__name__} {exc}".lower()
    return (
        "out of stock" in text
        or "outofstock" in text
        or "insufficient stock" in text
        or "insufficient inventory" in text
        or "not enough stock" in text
        or "stock shortage" in text
        or "short stock" in text
        or "stock short" in text
    )


def book_units(code, n):
