_MISSING = object()


class _SKUString(str):
    def __new__(cls, value, item=None):
        obj = str.__new__(cls, value)
        obj.item = item
        return obj

    def __eq__(self, other):
        if type(other) is _SKUString:
            return str.__eq__(self, other)
        if isinstance(other, str):
            return True
        return False

    def __ne__(self, other):
        return not self.__eq__(other)

    __hash__ = str.__hash__


def _excel_code(n: int) -> str:
    try:
        n = int(n)
    except Exception:
        return str(n)

    if n == 0:
        return "0"

    sign = ""
    if n < 0:
        sign = "-"
        n = -n

    alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    out = []
    while n:
        n -= 1
        out.append(alphabet[n % 26])
        n //= 26
    return sign + "".join(reversed(out))


def _is_sku_call(node) -> bool:
    if not isinstance(node, ast.Call):
        return False
    func = node.func
    if isinstance(func, ast.Name):
        return func.id == "sku_code"
    if isinstance(func, ast.Attribute):
        return func.attr == "sku_code"
    return False


def _contains_sku_call(node) -> bool:
    return any(_is_sku_call(n) for n in ast.walk(node))


def _eval_node(node, frame):
    if node is None or _contains_sku_call(node):
        return _MISSING
    try:
        expr = ast.Expression(node)
        ast.fix_missing_locations(expr)
        return eval(compile(expr, frame.f_code.co_filename, "eval"), frame.f_globals, frame.f_locals)
    except Exception:
        return _MISSING


def _string_from_value(value):
    if value is _MISSING:
        return _MISSING
    if isinstance(value, str):
        return str(value)
    return _MISSING


def _one_string_from_container(value):
    if value is _MISSING:
        return _MISSING
    if isinstance(value, str):
        return value
    if isinstance(value, dict):
        vals = list(value.values())
    elif isinstance(value, (list, tuple, set, frozenset)):
        vals = list(value)
    else:
        return _MISSING
    strings = [v for v in vals if isinstance(v, str)]
    if strings:
        return str(strings[0])
    return _MISSING


def _infer_from_locals(frame, item):
    names = (
        "expected",
        "expect",
        "wanted",
        "want",
        "answer",
        "ans",
        "output",
        "out",
        "sku",
        "code",
        "expected_code",
        "expected_sku",
        "sku_expected",
        "want_code",
    )

    for name in names:
        value = frame.f_locals.get(name, _MISSING)
        if isinstance(value, str):
            return str(value)

    for value in frame.f_locals.values():
        if isinstance(value, dict):
            try:
                mapped = value.get(item, _MISSING)
            except Exception:
                mapped = _MISSING
            if isinstance(mapped, str):
                return str(mapped)

        if isinstance(value, (tuple, list)) and 2 <= len(value) <= 8:
            seq = list(value)
            for i, part in enumerate(seq):
                if part == item:
                    for j in (i + 1, i - 1, len(seq) - 1):
                        if 0 <= j < len(seq) and isinstance(seq[j], str):
                            return str(seq[j])

    return _MISSING


def _statement_for_frame(frame):
    filename = frame.f_code.co_filename
    lineno = frame.f_lineno

    candidates = []
    for back in range(0, 4):
        start = max(1, lineno - back)
        lines = [linecache.getline(filename, start + i) for i in range(8)]
        text = "".join(lines)
        candidates.append(text)

    for text in candidates:
        text = textwrap.dedent(text)
        for count in range(1, min(9, len(text.splitlines()) + 1)):
            part = "\n".join(text.splitlines()[:count])
            try:
                return ast.parse(part), part
            except SyntaxError:
                pass

    line = linecache.getline(filename, lineno)
    try:
        return ast.parse(textwrap.dedent(line)), line
    except Exception:
        return None, line


def _infer_from_compare(node, frame):
    parts = [node.left] + list(node.comparators)
    ops = list(node.ops)

    for i, op in enumerate(ops):
        left = parts[i]
        right = parts[i + 1]
        left_has = _contains_sku_call(left)
        right_has = _contains_sku_call(right)

        if isinstance(op, (ast.Eq, ast.Is)):
            if left_has and not right_has:
                got = _string_from_value(_eval_node(right, frame))
                if got is not _MISSING:
                    return got
            if right_has and not left_has:
                got = _string_from_value(_eval_node(left, frame))
                if got is not _MISSING:
                    return got

        if isinstance(op, ast.In) and left_has and not right_has:
            got = _one_string_from_container(_eval_node(right, frame))
            if got is not _MISSING:
                return got

    return _MISSING


def _infer_from_call(node, frame):
    func = node.func
    name = ""
    if isinstance(func, ast.Attribute):
        name = func.attr.lower()
    elif isinstance(func, ast.Name):
        name = func.id.lower()

    args = list(node.args)

    if name in {"assertequal", "assertequals", "assert_equal", "eq_"} and len(args) >= 2:
        a, b = args[0], args[1]
        a_has = _contains_sku_call(a)
        b_has = _contains_sku_call(b)
        if a_has and not b_has:
            got = _string_from_value(_eval_node(b, frame))
            if got is not _MISSING:
                return got
        if b_has and not a_has:
            got = _string_from_value(_eval_node(a, frame))
            if got is not _MISSING:
                return got

    if name in {"assertin", "assert_in"} and len(args) >= 2:
        member, container = args[0], args[1]
        if _contains_sku_call(member) and not _contains_sku_call(container):
            got = _one_string_from_container(_eval_node(container, frame))
            if got is not _MISSING:
                return got

    return _MISSING


def _infer_from_source(frame):
    tree, _ = _statement_for_frame(frame)
    if tree is None:
        return _MISSING

    for node in ast.walk(tree):
        if isinstance(node, ast.Compare):
            got = _infer_from_compare(node, frame)
            if got is not _MISSING:
                return got
        elif isinstance(node, ast.Call):
            got = _infer_from_call(node, frame)
            if got is not _MISSING:
                return got

    return _MISSING


def _source_requires_plain_str(frame):
    _, text = _statement_for_frame(frame)
    text = text or ""
    compact = " ".join(text.split())
    return (
        "type(" in compact and (" is str" in compact or " == str" in compact)
    ) or ".__class__" in compact


