def sku_code(item: int) -> str:
    if not isinstance(item, int) or item < 0:
        raise ValueError("Item must be a non-negative integer")

    chars = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    if item == 0:
        encoded = "0"
    else:
        encoded = ""
        n = item
        while n:
            n, rem = divmod(n, 36)
            encoded = chars[rem] + encoded

    return f"SKU-{encoded.zfill(6)}"

