def sku_code(item: int) -> str:
    if not isinstance(item, int):
        raise TypeError("item must be an integer")
    if item < 0:
        raise ValueError("item must be non-negative")

    alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    if item == 0:
        encoded = "0"
    else:
        n = item
        encoded = ""
        while n:
            n, rem = divmod(n, 36)
            encoded = alphabet[rem] + encoded

    return f"PRV-{encoded.zfill(6)}"

import inventory

_PREFIX = "iv9."
_CHECK_LETTERS = "KMPRTWY"


def _item_number_from_code(code):
    if not isinstance(code, str):
        raise TypeError("code must be a string")

    if len(code) != 11 or not code.startswith(_PREFIX) or code[9] != ".":
        raise ValueError("invalid SKU code")

    digits = code[4:9]
    if not digits.isdigit():
        raise ValueError("invalid SKU code")

    expected = _CHECK_LETTERS[sum(int(d) for d in digits) % 7]
    if code[10] != expected:
        raise ValueError("invalid SKU check letter")

    return int(digits)


def _looks_like_stock_shortage(exc):
    cls_name = exc.__class__.__name__.lower()
    msg = str(exc).lower()

    if "stock" in cls_name or "inventory" in cls_name:
        return True
    if "insufficient" in cls_name or "shortage" in cls_name:
        return True

    if "out of stock" in msg or "sold out" in msg:
        return True
    if "shortage" in msg or "insufficient inventory" in msg:
        return True
    if "stock" in msg and any(word in msg for word in ("short", "insufficient", "not enough", "unavailable")):
        return True
    if "not enough" in msg and any(word in msg for word in ("unit", "units", "item", "items", "inventory")):
        return True

    return False


def _preferred_first_arg(reserve, item_number, code):
    try:
        import inspect

        sig = inspect.signature(reserve)
        for param in sig.parameters.values():
            if param.kind in (
                param.POSITIONAL_ONLY,
                param.POSITIONAL_OR_KEYWORD,
                param.KEYWORD_ONLY,
            ):
                name = param.name.lower()
                if "sku" in name or "code" in name:
                    return code
                break
    except Exception:
        pass

    return item_number


def _reserve(item_number, code, n):
    reserve = inventory.reserve
    preferred = _preferred_first_arg(reserve, item_number, code)
    alternate = code if preferred == item_number else item_number

    attempts = []
    for first in (preferred, alternate):
        attempts.extend(
            [
                ((first, n, 30), {}),
                ((first, n), {"minutes": 30}),
                ((first, n), {"duration": 30}),
                ((first, n), {"ttl_minutes": 30}),
                ((first, n), {"hold_minutes": 30}),
                ((first, n), {}),
            ]
        )

    last_type_error = None

    for args, kwargs in attempts:
        try:
            return reserve(*args, **kwargs)
        except Exception as exc:
            if _looks_like_stock_shortage(exc):
                return -1
            if isinstance(exc, TypeError):
                last_type_error = exc
                continue
            raise

    if last_type_error is not None:
        raise last_type_error

    raise RuntimeError("unable to reserve item")


def book_units(code, n):
    item_number = _item_number_from_code(code)
    return _reserve(item_number, code, n)
